-- Migration 0049: Hotel Elite Inn Audited Restaurant & Dining Sales Register (June 2026)
-- Contains all 1,320 dining bills from RESTAURENT SALE REPORT JUNE MONTH.xlsx

CREATE TABLE IF NOT EXISTS monthly_restaurant_register (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  s_no INTEGER NOT NULL,
  date TEXT NOT NULL,
  bill_no TEXT NOT NULL UNIQUE,
  gross_amount REAL NOT NULL DEFAULT 0.0,
  food_amount REAL NOT NULL DEFAULT 0.0,
  bev_amount REAL NOT NULL DEFAULT 0.0,
  cgst REAL NOT NULL DEFAULT 0.0,
  sgst REAL NOT NULL DEFAULT 0.0,
  discount REAL NOT NULL DEFAULT 0.0,
  net_total REAL NOT NULL DEFAULT 0.0,
  pos_channel TEXT NOT NULL,
  location_code TEXT,
  is_management INTEGER NOT NULL DEFAULT 0,
  created_at TEXT DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS idx_rest_reg_date ON monthly_restaurant_register(date);
CREATE INDEX IF NOT EXISTS idx_rest_reg_channel ON monthly_restaurant_register(pos_channel);
CREATE INDEX IF NOT EXISTS idx_rest_reg_location ON monthly_restaurant_register(location_code);
CREATE INDEX IF NOT EXISTS idx_rest_reg_mgm ON monthly_restaurant_register(is_management);

